
module Main_Controller_test;

	// Inputs
	reg [7:0] data_in;
	reg [7:0] IR;
	reg [7:0] R0;
	reg [7:0] R1;
	reg [1:0] enable;
	reg 	  clk;

	// Outputs
	wire [7:0] data_out;

	// Instantiate the Unit Under Test (UUT)
	Main_Controller uut (
		.data_in(data_in),
		.enable(enable),
		.clk(clk),
		.data_out(data_out),
		.IR(IR),
		.R0(R0),
		.R1(R1)
	);

	// Simulate system clock
	parameter    clk_period = 100;
    always     #(clk_period/2) clk = ~clk;    

	initial begin
		// Initialize Inputs
		clk = 1'b0;
		data_in = 8'b00000000;
		enable  = 2'b00;

		// Wait 50 ns for global reset to finish
		#50;
        
		// Add stimulus here: 1000 INPUTS

		// Reset all registers
		data_in = 8'b00000000;
		enable  = 2'b01;
		#100;
		data_in = 8'b00000000;
		enable  = 2'b10;
		#100;
		data_in = 8'b00000000;
		enable  = 2'b11;
		#100;

		// Add stimulus here


		
		$display("STARTING test_case_sub_00_00_0");

