		data_in = 8'b10000011;
		enable  = 2'b01;
		#100;

		// Load IR
		data_in = 8'b00010000; // data_out = R0 - R0
		enable  = 2'b11;	 
		#100;

		// Compute Data Out and Write Back
		data_in = 8'b00000000;
		enable  = 2'b00;	
		#100;
		
		// Verify correct output
        if (data_out != 8'b00000000) begin
			$display("OUTPUT ERROR: data_out is %b, expected %b", data_out, 8'b00000000);
		end
		if (IR[7] != 1'b0) begin
			$display("OVERFLOW ERROR: OVF is %b, expected %b", IR[7], 1'b0);
		end
		if (IR[6] != 1'b0) begin
			$display("SIGN ERROR: SGN is %b, expected %b", IR[6], 1'b0);
		end


		
